        HStack(spacing: 8) { TextField("说一句，或输入搜索", text: $text, axis: .vertical).focused($focused, equals: .homeInput).lineLimit(1...3).submitLabel(.search).onSubmit { openSearch() }; Button { openSearch() } label: { Image(systemName: "magnifyingglass").font(.title2).foregroundStyle(.blue.opacity(0.8)) }.accessibilityLabel("搜索") }.padding(.horizontal, 18).frame(minHeight: 70).background(.white.opacity(0.72), in: Capsule()).overlay(Capsule().stroke(.white.opacity(0.9), lineWidth: 1)).shadow(color: .blue.opacity(0.12), radius: 12, y: 5)
