    @EnvironmentObject private var model: AppModel; @State private var keyword: String; @State private var modules: Set<Module>; @State private var important: Bool; @State private var results: [Record] = []; @State private var selectedRecord: Record?; @FocusState private var focused: AppFocus?
    private let tags: [String]; private let dateStart: Date?; private let dateEnd: Date?; private let minimumAmount: Decimal?; private let minimumInclusive: Bool; private let maximumAmount: Decimal?; private let maximumInclusive: Bool; private let currency: String?; private let category: String?
    init(initialQuery: RecordQuery) { _keyword = State(initialValue: initialQuery.keyword); _modules = State(initialValue: initialQuery.modules); _important = State(initialValue: initialQuery.importantOnly); tags = initialQuery.tags; dateStart = initialQuery.dateStart; dateEnd = initialQuery.dateEnd; minimumAmount = initialQuery.minimumAmount; minimumInclusive = initialQuery.minimumInclusive; maximumAmount = initialQuery.maximumAmount; maximumInclusive = initialQuery.maximumInclusive; currency = initialQuery.currency; category = initialQuery.category }
    var body: some View { ScrollView { VStack(spacing: 18) { searchCard("自动总额", "sum", .blue) { if totalKeys.isEmpty { Text("—").font(.title.bold()).foregroundStyle(.secondary) } else { LazyVGrid(columns: [.init(.flexible()), .init(.flexible())], spacing: 10) { ForEach(totalKeys, id: \.self) { key in HStack { VStack(alignment: .leading, spacing: 5) { Text(key).font(.caption).foregroundStyle(.secondary); Text(String(describing: totalMap[key] ?? 0)).font(.title2.bold()).foregroundStyle(.blue) }; Spacer(); Image(systemName: "banknote.fill").foregroundStyle(Color.blue.opacity(0.35)) }.padding(14).background(Color.blue.opacity(0.09), in: RoundedRectangle(cornerRadius: 18)) } } } }; searchCard("查询条件", "slider.horizontal.3", .purple) { HStack { Image(systemName: "magnifyingglass").foregroundStyle(.secondary); TextField("关键词", text: $keyword).focused($focused, equals: .searchInput).submitLabel(.search).onSubmit { focused = nil; search() }; if !keyword.isEmpty { Button { keyword = "" } label: { Image(systemName: "xmark.circle.fill").foregroundStyle(.secondary) } } }.padding(15).background(.white.opacity(0.68), in: RoundedRectangle(cornerRadius: 20)); LazyVGrid(columns: [.init(.flexible()), .init(.flexible())], spacing: 9) { ForEach(Module.allCases) { module in Button { if modules.contains(module) { modules.remove(module) } else { modules.insert(module) } } label: { Label(module.title, systemImage: module.icon).frame(maxWidth: .infinity) }.buttonStyle(.borderedProminent).tint(modules.contains(module) ? module.color : .gray.opacity(0.22)) } }; Toggle("重要", isOn: $important).padding(13).background(.white.opacity(0.48), in: RoundedRectangle(cornerRadius: 16)); if dateStart != nil || minimumAmount != nil || maximumAmount != nil || category != nil || !tags.isEmpty { Text(filterSummary).font(.caption).foregroundStyle(.secondary) } }; searchCard("结果 \(results.count)", "list.bullet", .indigo) { VStack(spacing: 10) { ForEach(results) { record in Button { focused = nil; selectedRecord = record } label: { SearchResultRow(record: record).padding(.horizontal, 12).contentShape(Rectangle()) }.buttonStyle(.plain).background(.white.opacity(0.58), in: RoundedRectangle(cornerRadius: 18)).overlay(RoundedRectangle(cornerRadius: 18).stroke(.white.opacity(0.8))) } } } }.padding(16).background(Color.clear.contentShape(Rectangle()).onTapGesture { focused = nil }) }.scrollDismissesKeyboard(.interactively).background(LakeBackground()).navigationTitle("搜索").navigationBarTitleDisplayMode(.inline).navigationDestination(item: $selectedRecord) { DetailView(record: $0) }.onAppear { focused = nil; search() }.onDisappear { focused = nil }.onChange(of: keyword) { search() }.onChange(of: modules) { search() }.onChange(of: important) { search() }.toolbar { ToolbarItemGroup(placement: .keyboard) { Spacer(); Button("完成") { focused = nil } } } }
    private var totalMap: [String: Decimal] { QuickNoteCore.numericTotals(in: results) }
    private var totalKeys: [String] { totalMap.keys.sorted() }
    private var filterSummary: String { [dateStart == nil ? nil : "日期范围", minimumAmount.map { "金额 \(minimumInclusive ? "≥" : ">") \($0)" }, maximumAmount.map { "金额 \(maximumInclusive ? "≤" : "<") \($0)" }, currency, category, tags.isEmpty ? nil : tags.joined(separator: "、")].compactMap { $0 }.joined(separator: " · ") }
    private func search() { do { results = try model.core.search(RecordQuery(keyword: keyword, modules: modules, importantOnly: important, tags: tags, dateStart: dateStart, dateEnd: dateEnd, minimumAmount: minimumAmount, minimumInclusive: minimumInclusive, maximumAmount: maximumAmount, maximumInclusive: maximumInclusive, currency: currency, category: category)) } catch { model.error = error.localizedDescription } }
    private func searchCard<Content: View>(_ title: String, _ icon: String, _ color: Color, @ViewBuilder content: () -> Content) -> some View { VStack(alignment: .leading, spacing: 15) { HStack { Image(systemName: icon).foregroundStyle(color).frame(width: 42, height: 42).background(color.opacity(0.13), in: RoundedRectangle(cornerRadius: 13)); Text(title).font(.title2.bold()).foregroundStyle(AppTheme.primary); Spacer() }; content() }.frame(maxWidth: .infinity, alignment: .leading).padding(18).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 28)).background(color.opacity(0.035), in: RoundedRectangle(cornerRadius: 28)).overlay(RoundedRectangle(cornerRadius: 28).stroke(.white.opacity(0.95), lineWidth: 1.2)).shadow(color: color.opacity(0.15), radius: 16, y: 8) }
}

struct SearchResultRow: View { let record: Record; var body: some View { HStack(spacing: 12) { Image(systemName: record.module.icon).foregroundStyle(record.module.color).frame(width: 42, height: 42).background(record.module.color.opacity(0.12), in: RoundedRectangle(cornerRadius: 12)); VStack(alignment: .leading, spacing: 4) { Text(record.content).font(.headline).lineLimit(1); Text(record.rawInput).font(.caption).foregroundStyle(.secondary).lineLimit(1); HStack { Text(record.module.title); ForEach(record.tags.prefix(2), id: \.self) { Text($0) } }.font(.caption2).foregroundStyle(record.module.color) }; Spacer(); VStack(alignment: .trailing) { Text(record.occurredAt ?? record.createdAt, style: .date).font(.caption).foregroundStyle(.secondary); ForEach(record.amountItems.prefix(3), id: \.self) { Text("\($0.currency ?? "") \($0.value)").font(.headline).foregroundStyle(.blue) } }; Image(systemName: "chevron.right").foregroundStyle(.secondary) }.padding(.vertical, 12).frame(maxWidth: .infinity).contentShape(Rectangle()) } }

struct DetailView: View {
    @EnvironmentObject private var model: AppModel; @Environment(\.dismiss) private var dismiss; @State private var record: Record; @State private var lastParsedRaw: String
    init(record: Record) { _record = State(initialValue: record); _lastParsedRaw = State(initialValue: record.rawInput) }
    var body: some View { RecordForm(record: $record, showRawInput: true, showsDetailSummary: true, onSave: saveAndDismiss, onAutoSave: save).navigationTitle("记录详情").navigationBarTitleDisplayMode(.inline).toolbar { ToolbarItemGroup(placement: .bottomBar) { ShareLink(item: shareText) { Label("分享", systemImage: "square.and.arrow.up") }; Spacer(); ShareLink(item: shareText) { Label("导出", systemImage: "doc") }; Spacer(); Menu { Button("复制内容") { UIPasteboard.general.string = shareText } } label: { Label("更多", systemImage: "ellipsis") } } }.task(id: record.rawInput) { try? await Task.sleep(for: .milliseconds(400)); guard !Task.isCancelled, record.rawInput != lastParsedRaw else { return }; await reparseAndSave() } }
    private var shareText: String { [record.content, record.rawInput == record.content ? nil : record.rawInput].compactMap { $0 }.joined(separator: "\n\n") }
    private func save(_ value: Record) { do { try model.save(value); record = value } catch { model.error = error.localizedDescription } }
    private func saveAndDismiss(_ value: Record) { do { try model.save(value); record = value; dismiss() } catch { model.error = error.localizedDescription } }
    private func reparseAndSave() async { let raw = record.rawInput.trimmed; guard !raw.isEmpty else { return }; do { if case .create(var parsed) = try await model.parser.parse(raw) { parsed.id = record.id; parsed.ownerID = record.ownerID; parsed.createdAt = record.createdAt; parsed.important = record.important; lastParsedRaw = raw; save(parsed) } } catch { model.error = "重新解析失败，已保留当前记录。" } }
}

struct RecordForm: View {
    @EnvironmentObject private var model: AppModel; @Binding var record: Record; let showRawInput: Bool; let showsDetailSummary: Bool; let saveTitle: String; let onSave: (Record) -> Void; let onSearch: ((Record) -> Void)?; let onReparse: (() -> Void)?; let onVoice: (() -> Void)?; let onAutoSave: ((Record) -> Void)?; let isRecording: Bool; let voiceLabel: String
    @State private var tags: String; @State private var amount: String; @State private var attachmentMenu = false; @State private var photos = false; @State private var camera = false; @State private var photo: PhotosPickerItem?; @FocusState private var focused: AppFocus?
