    @ViewBuilder private var moduleFields: some View { switch record.module { case .ledger: VStack(spacing: 12) { fieldCard("商家", "storefront.fill", .blue) { optional("商家", $record.merchant, .merchant) }; if record.amountItems.count > 1 { card(title: "金额明细", icon: "banknote.fill", color: .orange) { LazyVGrid(columns: [.init(.flexible()), .init(.flexible())], spacing: 10) { ForEach(record.amountItems, id: \.self) { item in VStack(alignment: .leading) { Text(item.currency ?? "未标币种").font(.caption).foregroundStyle(.secondary); Text(String(describing: item.value)).font(.title3.bold()) }.frame(maxWidth: .infinity, alignment: .leading).padding(12).background(.white.opacity(0.58), in: RoundedRectangle(cornerRadius: 15)) } } } } else { HStack(alignment: .top, spacing: 12) { fieldCard("金额", "banknote.fill", .orange) { TextField("金额", text: $amount).keyboardType(.decimalPad).focused($focused, equals: .amount) }; fieldCard("货币", "coloncurrencysign.circle.fill", .green) { optional("币种", $record.currency, .currency) } } }; HStack(alignment: .top, spacing: 12) { fieldCard("类别", "tag.fill", .purple) { optional("类别", $record.category, .category) }; fieldCard("支付方式", "creditcard.fill", .orange) { optional("支付方式", $record.paymentMethod, .payment) } }; HStack(alignment: .top, spacing: 12) { fieldCard("地点", "mappin.circle.fill", .mint) { optional("地点", $record.location, .location) }.frame(maxWidth: .infinity); fieldCard("日期时间", "calendar", .indigo) { date("日期时间", $record.occurredAt) }.frame(maxWidth: .infinity) } }; case .todo: VStack(spacing: 12) { card(title: "待办时间", icon: "calendar", color: .indigo) { date("日期时间", $record.dueAt) }; HStack { card(title: "提醒", icon: "bell.fill", color: .orange) { Toggle("提醒", isOn: $record.reminderEnabled) }; card(title: "状态", icon: "checkmark.circle.fill", color: .green) { Picker("状态", selection: Binding(get: { record.status ?? .pending }, set: { record.status = $0 })) { ForEach(TodoStatus.allCases, id: \.self) { Text($0.rawValue).tag($0) } } } }; card(title: "地点", icon: "mappin.circle.fill", color: .mint) { optional("地点", $record.location, .location) } }; case .memo: card(title: "提醒", icon: "bell.fill", color: .orange) { Toggle("提醒", isOn: $record.reminderEnabled) }; case .idea: EmptyView() } }
    private func card<Content: View>(title: String? = nil, icon: String? = nil, color: Color = .blue, trailing: (() -> Void)? = nil, @ViewBuilder content: () -> Content) -> some View { VStack(alignment: .leading, spacing: 13) { if let title { HStack { if let icon { Image(systemName: icon).font(.headline).foregroundStyle(color).frame(width: 40, height: 40).background(color.opacity(0.14), in: RoundedRectangle(cornerRadius: 13)) }; Text(title).font(.headline).foregroundStyle(AppTheme.primary); Spacer(); if let trailing { Button(action: trailing) { Image(systemName: "arrow.clockwise").frame(width: 34, height: 34).background(.white.opacity(0.7), in: Circle()) } } } }; content() }.frame(maxWidth: .infinity, alignment: .leading).padding(17).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 26)).background(LinearGradient(colors: [.white.opacity(0.72), color.opacity(0.055)], startPoint: .topLeading, endPoint: .bottomTrailing), in: RoundedRectangle(cornerRadius: 26)).overlay(RoundedRectangle(cornerRadius: 26).stroke(.white.opacity(0.95), lineWidth: 1.2)).shadow(color: color.opacity(0.14), radius: 14, y: 7) }
    private func fieldCard<Content: View>(_ title: String, _ icon: String, _ color: Color, @ViewBuilder content: () -> Content) -> some View { card(title: title, icon: icon, color: color) { content() }.frame(minHeight: 112, alignment: .top) }
    private func optional(_ title: String, _ value: Binding<String?>, _ field: AppFocus) -> some View { TextField(title, text: Binding(get: { value.wrappedValue ?? "" }, set: { value.wrappedValue = $0.isEmpty ? nil : $0 })).focused($focused, equals: field).submitLabel(.done).onSubmit { focused = nil } }
    private func date(_ title: String, _ value: Binding<Date?>) -> some View { VStack(alignment: .leading) { Toggle("设置", isOn: Binding(get: { value.wrappedValue != nil }, set: { value.wrappedValue = $0 ? Date() : nil })); if value.wrappedValue != nil { DatePicker(title, selection: Binding(get: { value.wrappedValue! }, set: { value.wrappedValue = $0 }), displayedComponents: [.date, .hourAndMinute]).labelsHidden() } } }
    private func autoSave() { guard onAutoSave != nil, let value = prepared() else { return }; onAutoSave?(value) }
    private func prepared() -> Record? { focused = nil; var value = record; value.tags = tags.csv; guard amount.isEmpty || Decimal(string: amount) != nil else { model.error = "金额格式无效"; return nil }; if value.module == .ledger, value.amountItems.count <= 1 { value.amount = amount.isEmpty ? nil : Decimal(string: amount); value.amountItems = value.amount.map { [AmountItem(value: $0, currency: value.currency)] } ?? [] }; record = value; return value }
}

struct RecordRow: View { let record: Record; var body: some View { VStack(alignment: .leading) { Text(record.content).lineLimit(2); Text(record.occurredAt ?? record.createdAt, style: .date).font(.caption).foregroundStyle(.secondary) } } }

struct CameraPicker: UIViewControllerRepresentable {
    @Environment(\.dismiss) private var dismiss
    func makeCoordinator() -> Coordinator { Coordinator(dismiss: dismiss) }
    func makeUIViewController(context: Context) -> UIImagePickerController { let picker = UIImagePickerController(); picker.sourceType = .camera; picker.delegate = context.coordinator; return picker }
    func updateUIViewController(_ uiViewController: UIImagePickerController, context: Context) {}
    final class Coordinator: NSObject, UIImagePickerControllerDelegate, UINavigationControllerDelegate { let dismiss: DismissAction; init(dismiss: DismissAction) { self.dismiss = dismiss }; func imagePickerController(_ picker: UIImagePickerController, didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey: Any]) { dismiss() }; func imagePickerControllerDidCancel(_ picker: UIImagePickerController) { dismiss() } }
}

@MainActor final class SpeechInput: ObservableObject {
    enum Phase { case idle, listening, processing }
    @Published var transcript = ""; @Published var finishedTranscript: String?; @Published var phase: Phase = .idle; @Published var error: String?
    var isRecording: Bool { phase == .listening }; var statusText: String { phase == .listening ? "正在听…" : phase == .processing ? "正在识别…" : "语音补充" }
    let primaryLocale = Locale(identifier: "zh-CN")
    let secondaryLocale = Locale(identifier: "en-US")
    private let engine = AVAudioEngine(); private var task: SFSpeechRecognitionTask?; private var request: SFSpeechAudioBufferRecognitionRequest?; private var tapInstalled = false
    func start() { SFSpeechRecognizer.requestAuthorization { [weak self] status in Task { @MainActor in guard status == .authorized else { self?.error = "请允许语音识别权限。"; return }; AVAudioApplication.requestRecordPermission { allowed in Task { @MainActor in guard allowed else { self?.error = "请允许麦克风权限。"; return }; self?.begin() } } } } }
    private func begin() { tearDown(); transcript = ""; finishedTranscript = nil; guard let recognizer = SFSpeechRecognizer(locale: primaryLocale), recognizer.isAvailable else { error = "系统语音识别不可用。"; return }; let request = SFSpeechAudioBufferRecognitionRequest(); request.shouldReportPartialResults = true; request.contextualStrings = ["沃尔玛", "Target", "Costco", "Amazon", "Visa", "Starbucks", "iPhone"]; self.request = request; let node = engine.inputNode; node.installTap(onBus: 0, bufferSize: 1024, format: node.outputFormat(forBus: 0)) { buffer, _ in request.append(buffer) }; tapInstalled = true; task = recognizer.recognitionTask(with: request) { [weak self] result, failure in Task { @MainActor in guard let self else { return }; if let result { self.transcript = result.bestTranscription.formattedString }; if failure != nil || result?.isFinal == true { self.finish() } } }; do { try AVAudioSession.sharedInstance().setCategory(.record, mode: .measurement); try AVAudioSession.sharedInstance().setActive(true); engine.prepare(); try engine.start(); phase = .listening } catch { tearDown(); self.error = "无法启动麦克风：\(error.localizedDescription)" } }
    private func finish() { guard request != nil || task != nil else { return }; phase = .processing; let finalText = transcript; tearDown(); if !finalText.trimmed.isEmpty { finishedTranscript = finalText }; phase = .idle }
    func stop() { guard phase != .idle else { return }; finish() }
    private func tearDown() { if engine.isRunning { engine.stop() }; if tapInstalled { engine.inputNode.removeTap(onBus: 0); tapInstalled = false }; request?.endAudio(); task?.cancel(); request = nil; task = nil }
}

private extension String { var trimmed: String { trimmingCharacters(in: .whitespacesAndNewlines) }; var csv: [String] { split(separator: ",").map { String($0).trimmed }.filter { !$0.isEmpty } } }
private extension Module { var icon: String { switch self { case .ledger: "chart.bar.fill"; case .todo: "checkmark.square.fill"; case .memo: "note.text"; case .idea: "lightbulb.fill" } }; var decoration: String { switch self { case .ledger: "creditcard.fill"; case .todo: "checklist"; case .memo: "note.text"; case .idea: "sparkles" } }; var subtitle: String { switch self { case .ledger: "轻松记账，清楚每一笔"; case .todo: "记下任务，安心完成"; case .memo: "随手记录，整理生活"; case .idea: "闪现的想法，值得记录" } }; var color: Color { switch self { case .ledger: AppTheme.ledgerAccent; case .todo: AppTheme.todoAccent; case .memo: AppTheme.memoAccent; case .idea: AppTheme.ideaAccent } } }
